INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — Equity multiplier in DuPont analysis
(4, 'Capital Structure and Valuation', 'What does the equity multiplier measure in the DuPont analysis framework?', '["The ratio of net income to total revenue", "The ratio of total debt to total equity", "The ratio of total assets to shareholders'' equity, reflecting the degree of financial leverage", "The ratio of operating income to interest expense"]'::jsonb, 2, 'Under ASC 280 and the DuPont framework, the equity multiplier (total assets ÷ shareholders'' equity) measures how much of a firm''s asset base is financed by equity versus debt, reflecting financial leverage. ROE = profit margin × asset turnover × equity multiplier. A higher multiplier indicates greater leverage. Choice B is incorrect because the debt-to-equity ratio directly compares debt to equity, while the equity multiplier captures leverage through the total assets-to-equity relationship.', 'easy', 1),

-- Q2: medium / L2 — Free cash flow to the firm calculation
(4, 'Capital Structure and Valuation', 'Graystone Manufacturing reports EBIT of $4,200,000, depreciation of $600,000, capital expenditures of $900,000, and a $250,000 increase in net working capital. The tax rate is 25%. Calculate Graystone''s free cash flow to the firm.', '["$2,600,000", "$2,850,000", "$3,100,000", "$3,650,000"]'::jsonb, 0, 'Free cash flow to the firm equals EBIT × (1 − tax rate) + depreciation − capital expenditures − change in working capital. Under ASC 230 (Statement of Cash Flows), FCFF = $4,200,000 × 0.75 + $600,000 − $900,000 − $250,000 = $2,600,000. Choice D ($3,650,000) is incorrect because it uses pre-tax EBIT, failing to account for the corporate tax obligation on operating earnings.', 'medium', 2),

-- Q3: medium / L3 — Asset impairment impact on debt covenants
(4, 'Capital Structure and Valuation', 'Thornfield Manufacturing has total debt of $24,000,000 and total equity of $16,000,000 (D/E of 1.5). A $4,000,000 goodwill impairment charge is recorded under ASC 350. The debt covenant requires D/E below 2.0. Analyze the impact of the impairment on covenant compliance.', '["D/E remains at 1.5 because impairments affect only the income statement", "D/E increases to 1.75 because only half the impairment reduces equity", "D/E decreases to 1.33 because the impairment reduces total assets and debt capacity", "D/E increases to 2.0, placing Thornfield at the covenant boundary and at risk of technical default"]'::jsonb, 3, 'Under ASC 350-20, goodwill impairment reduces the carrying amount of goodwill and is recognized as a loss, directly decreasing shareholders'' equity. The $4,000,000 charge reduces equity from $16,000,000 to $12,000,000, pushing D/E from 1.5 to 2.0 ($24M / $12M). Choice A is incorrect because impairment charges flow through the income statement and reduce retained earnings, a component of equity on the balance sheet.', 'medium', 3),

-- Q4: medium / L3 — Convertible bond conversion effect on WACC
(4, 'Capital Structure and Valuation', 'Ashbury Holdings has $10,000,000 in convertible bonds at 4% interest. If all bondholders convert into 200,000 shares of common stock, the tax rate is 25%, and the cost of equity is 12%, analyze the most likely effect on the firm''s weighted average cost of capital.', '["WACC decreases because eliminating debt reduces financial risk", "WACC increases because 3% after-tax debt is replaced by 12% equity, raising the blended cost", "WACC is unchanged because total firm value remains constant under M-M assumptions", "WACC decreases because removing interest payments increases free cash flow"]'::jsonb, 1, 'When convertible bonds convert, the capital structure shifts from lower-cost debt to higher-cost equity. The after-tax cost of debt was 4% × (1 − 0.25) = 3%, far below the 12% cost of equity. Under ASC 470-20, conversion eliminates the debt liability and increases common equity, raising the weighted average cost. Choice A is incorrect because while financial risk decreases, the removal of tax-advantaged, lower-cost debt raises the overall blended cost of capital.', 'medium', 3),

-- Q5: medium / L3 — DuPont analysis: leverage effect on ROE
(4, 'Capital Structure and Valuation', 'Evergreen Corp. has a net profit margin of 8%, asset turnover of 1.2, and an equity multiplier of 1.5, yielding ROE of 14.4%. Hawthorne Inc. has the same margin and turnover but an equity multiplier of 2.5. Analyze how Hawthorne''s greater financial leverage affects its ROE.', '["Hawthorne''s ROE is 14.4%, identical to Evergreen, because profitability and efficiency are the same", "Hawthorne''s ROE is 16.8% because the equity multiplier adds a fixed premium", "Hawthorne''s ROE is 24.0% because the higher equity multiplier amplifies returns to equity holders proportionally", "Hawthorne''s ROE is 20.0% because leverage adds a constant 5.6% premium"]'::jsonb, 2, 'Under the DuPont framework consistent with ASC 280 financial analysis, ROE = profit margin × asset turnover × equity multiplier. Hawthorne''s ROE = 8% × 1.2 × 2.5 = 24.0%, compared to Evergreen''s 14.4%. The equity multiplier''s multiplicative effect means higher leverage amplifies returns to shareholders. Choice A is incorrect because it assumes ROE depends only on operational performance, ignoring the leverage component that is central to DuPont decomposition.', 'medium', 3),

-- Q6: easy / L1 — Financial slack definition
(4, 'Capital Structure and Valuation', 'What does financial slack refer to in capital structure theory?', '["Reserves of cash, marketable securities, and unused borrowing capacity that allow a firm to fund investments quickly", "The amount by which a firm''s actual debt exceeds its optimal debt level", "The difference between a firm''s current dividend and its maximum sustainable dividend", "The portion of a firm''s assets pledged as collateral to secured lenders"]'::jsonb, 0, 'Under ASC 505 equity principles and the pecking order theory (Myers, 1984), financial slack includes liquid assets and unused debt capacity that provide flexibility to fund positive-NPV projects without issuing costly external securities. Firms maintain slack to avoid adverse selection costs of external financing. Choice B is incorrect because excess debt beyond the optimal level describes overleveraging, not the cushion of available internal and low-cost funding that defines financial slack.', 'easy', 1),

-- Q7: medium / L3 — Residual dividend policy application
(4, 'Capital Structure and Valuation', 'Calloway Technologies follows a strict residual dividend policy. The firm generated $8,000,000 in net income and has $10,000,000 in positive-NPV projects. Its target capital structure is 60% equity and 40% debt. Analyze whether Calloway will pay a dividend this year.', '["No dividend, because the total capital budget exceeds the firm''s net income", "A dividend of $4,000,000, equal to net income minus the debt-financed portion", "No dividend, because the residual policy requires retaining 100% of earnings when positive-NPV projects exist", "A dividend of $2,000,000, because only $6,000,000 of equity is needed to fund projects at the target structure"]'::jsonb, 3, 'Under the residual dividend model consistent with ASC 505-20, dividends equal earnings minus the equity portion of capital expenditures. Calloway needs $6,000,000 in equity (60% × $10,000,000) from $8,000,000 in net income, leaving a $2,000,000 residual dividend. Choice C is incorrect because the residual policy does not require retaining all earnings — only the amount needed to maintain the target capital structure for planned investments.', 'medium', 3),

-- Q8: hard / L4 — APV vs WACC for LBO with changing leverage
(4, 'Capital Structure and Valuation', 'Beacon Capital is evaluating a leveraged buyout of Dorset Industries. The deal involves $30,000,000 in acquisition debt that will be aggressively repaid over five years, with $8,000,000 retired in year one alone. The target''s unlevered cost of equity is 11% and the tax rate is 25%. Evaluate which valuation method is most appropriate.', '["The WACC method, because it handles changing leverage using a single blended discount rate", "The adjusted present value method, because it separately values unlevered cash flows and time-varying tax shields when leverage shifts materially over time", "The dividend discount model, because LBO returns depend on distributions to equity holders", "The comparable company method, because market multiples incorporate leverage effects automatically"]'::jsonb, 1, 'The APV approach (Myers, 1974) separately discounts unlevered cash flows and time-varying tax shields, making it ideal when capital structure shifts materially — as in an LBO with aggressive paydown. Under valuation principles consistent with ASC 820-10-35, this avoids the WACC method''s constant-leverage assumption. Choice A is incorrect because standard WACC uses a fixed blended rate that misprices cash flows when debt-to-equity changes significantly each year.', 'hard', 4),

-- Q9: medium / L2 — Interest coverage ratio calculation
(4, 'Capital Structure and Valuation', 'Alderton Holdings reports EBIT of $4,000,000 and total interest expense of $1,000,000 for fiscal year 2025. Alderton''s credit agreement requires a minimum interest coverage ratio of 3.5x. Determine the coverage ratio and whether Alderton satisfies the covenant.', '["3.0x; Alderton violates the covenant", "5.0x; Alderton exceeds the covenant", "4.0x; Alderton exceeds the covenant", "2.25x; Alderton violates the covenant"]'::jsonb, 2, 'The interest coverage ratio equals EBIT ÷ interest expense = $4,000,000 ÷ $1,000,000 = 4.0x, which exceeds Alderton''s 3.5x covenant minimum. Under ASC 470-10 debt classification guidance, coverage ratios measure a firm''s ability to service debt from operating earnings. Choice A (3.0x) is incorrect because it subtracts interest from EBIT before dividing, computing ($4M − $1M) / $1M, which double-counts the interest charge.', 'medium', 2),

-- Q10: easy / L1 — Market-to-book ratio interpretation
(4, 'Capital Structure and Valuation', 'What does a market-to-book ratio greater than 1.0 indicate about a company?', '["The company is insolvent because liabilities exceed assets", "The company''s stock price has declined below its offering price", "The company''s total debt exceeds its total equity on the balance sheet", "The market values the company''s equity above its book value, suggesting expected future growth or intangible value"]'::jsonb, 3, 'Under ASC 820 fair value principles, the market-to-book ratio compares market capitalization to book value of equity. A ratio above 1.0 means investors pay more than recorded net asset value, reflecting expectations of future earnings growth, brand value, or intangibles not captured on the balance sheet. Choice A is incorrect because insolvency relates to negative equity or inability to meet obligations, not to the market-to-book relationship.', 'easy', 1),

-- Q11: easy / L1 — Capital rationing definition
(4, 'Capital Structure and Valuation', 'What does capital rationing mean when a firm evaluates its investment opportunities?', '["A method of calculating the optimal dividend payout ratio", "A constraint that limits the total amount a firm can invest, forcing selection among positive-NPV projects", "A tax strategy that minimizes the cost of debt financing", "A regulation requiring firms to maintain minimum equity reserves"]'::jsonb, 1, 'Under ASC 820 and capital budgeting principles, capital rationing occurs when a firm imposes a budget ceiling on capital expenditures, forcing selection among competing positive-NPV projects because available funds are insufficient to pursue all of them. It can be soft (internally imposed) or hard (externally imposed by lenders). Choice D is incorrect because capital rationing is an investment constraint, not a regulatory reserve requirement.', 'easy', 1),

-- Q12: medium / L2 — Degree of operating leverage calculation
(4, 'Capital Structure and Valuation', 'Granite Construction reports sales of $10,000,000, variable costs of $6,000,000, and fixed operating costs of $2,400,000 for fiscal year 2025. Calculate Granite''s degree of operating leverage at the current sales level.', '["2.50", "1.67", "4.17", "0.40"]'::jsonb, 0, 'Under ASC 280 operating analysis, the degree of operating leverage equals contribution margin divided by EBIT. For Granite: ($10,000,000 − $6,000,000) ÷ ($10,000,000 − $6,000,000 − $2,400,000) = $4,000,000 ÷ $1,600,000 = 2.50, meaning a 1% change in sales produces a 2.5% change in EBIT. Choice B (1.67) is incorrect because it divides sales by variable costs, measuring the cost ratio rather than operating leverage.', 'medium', 2),

-- Q13: medium / L3 — Below-market equity issuance dilution
(4, 'Capital Structure and Valuation', 'Fairview Technologies has 5,000,000 shares outstanding at $40 per share and announces a seasoned equity offering of 1,000,000 new shares at $36. Analyze the immediate effect on existing shareholders'' wealth per share.', '["Value per share remains at $40.00 because markets efficiently absorb new shares", "Value per share drops to $36.00 because all shares converge to the offering price", "Value per share declines to approximately $39.33 because the below-market issuance dilutes existing shareholders", "Value per share increases to $41.00 because additional capital strengthens the balance sheet"]'::jsonb, 2, 'Issuing 1,000,000 shares at $36 raises $36,000,000, bringing total equity to $236,000,000 over 6,000,000 shares, or approximately $39.33. Under ASC 505-10 equity disclosure principles, below-market issuance transfers wealth from existing to new shareholders. Choice B is incorrect because existing shares do not drop to the offering price — the weighted average of old market value and new issuance proceeds determines the post-offering price.', 'medium', 3),

-- Q14: medium / L2 — Terminal value using perpetuity growth method
(4, 'Capital Structure and Valuation', 'Bridgewater Consulting projects free cash flow of $2,000,000 in year 5 of a discounted cash flow analysis. The firm''s WACC is 10% and the long-term growth rate is 2%. Using the perpetuity growth method, calculate the terminal value at the end of year 5.', '["$25,000,000", "$20,400,000", "$20,000,000", "$25,500,000"]'::jsonb, 3, 'Under the Gordon Growth perpetuity model consistent with ASC 820-10-35, terminal value = FCF₅ × (1 + g) / (WACC − g) = $2,000,000 × 1.02 / (0.10 − 0.02) = $2,040,000 / 0.08 = $25,500,000. The year-5 cash flow must be grown one period to represent the year-6 starting flow. Choice A ($25,000,000) is incorrect because it uses the year-5 FCF without growing it forward, understating terminal value by $500,000.', 'medium', 2),

-- Q15: medium / L3 — Asset sale to retire debt affects WACC
(4, 'Capital Structure and Valuation', 'Lockwood Industries sells a non-core division for $8,000,000 and uses the full proceeds to retire outstanding debt. Before the transaction, Lockwood has 50% debt (after-tax cost 4%) and 50% equity (cost 13%). Analyze the most likely effect on WACC.', '["WACC increases because a larger proportion of capital is now financed by higher-cost equity", "WACC decreases because removing debt reduces financial risk and the overall cost", "WACC remains unchanged because the asset sale and debt retirement are offsetting transactions", "WACC decreases because the tax shield from debt was not being fully utilized"]'::jsonb, 0, 'Retiring debt with asset sale proceeds shifts the capital structure toward equity. With after-tax debt at 4% and equity at 13%, reducing the cheaper component''s weight increases the blended cost. Under capital structure analysis consistent with ASC 470-10, the new equity-heavy mix raises WACC. Choice B is incorrect because while financial risk declines, the mechanical increase in the equity proportion — the most expensive component — dominates the WACC calculation.', 'medium', 3),

-- Q16: hard / L4 — Evaluate M-M with taxes critique
(4, 'Capital Structure and Valuation', 'Barrett Chemicals has a tax rate of 25% and $40,000,000 in outstanding debt. An analyst applies M-M with taxes, calculating a tax shield of $10,000,000, and recommends increasing leverage to maximize firm value. However, Barrett operates in a volatile commodity market with a recent 40% EBITDA decline. Evaluate the recommendation.', '["The analyst is correct because M-M with taxes proves more debt always increases firm value", "The analyst is incorrect because M-M with taxes ignores financial distress costs, which for a volatile commodity firm likely offset any incremental tax shield from additional leverage", "The analyst is correct but should wait until commodity prices recover before adding debt", "The recommendation is irrelevant because interest tax shields have no real impact on valuation"]'::jsonb, 1, 'While M-M with taxes (VL = VU + t × D) shows firm value increases with debt via tax shields, this model assumes no bankruptcy costs. Under the trade-off theory consistent with ASC 470 debt guidance, optimal leverage balances tax benefits against expected distress costs. Barrett''s volatile EBITDA makes additional debt dangerous — marginal distress costs likely exceed marginal tax benefits. Choice A is incorrect because it uncritically applies M-M''s frictionless conclusion, ignoring real-world distress costs that erode incremental tax shields.', 'hard', 4),

-- Q17: medium / L2 — Unlevered free cash flow calculation
(4, 'Capital Structure and Valuation', 'Northbrook Industries reports EBIT of $3,000,000, depreciation of $500,000, capital expenditures of $700,000, and a $200,000 increase in net working capital. The tax rate is 20%. Calculate the unlevered free cash flow.', '["$2,600,000", "$2,400,000", "$1,500,000", "$2,000,000"]'::jsonb, 3, 'Unlevered free cash flow equals EBIT × (1 − tax rate) + depreciation − capital expenditures − change in working capital. Under ASC 230, UFCF = $3,000,000 × 0.80 + $500,000 − $700,000 − $200,000 = $2,000,000. This measure excludes interest effects, isolating operating cash generation. Choice A ($2,600,000) is incorrect because it uses pre-tax EBIT, overstating cash flow by ignoring the 20% tax obligation.', 'medium', 2),

-- Q18: hard / L4 — IRR vs NPV for mutually exclusive projects
(4, 'Capital Structure and Valuation', 'Wainwright Corp. must choose between two mutually exclusive projects. Project X requires $2,000,000 and has an IRR of 22% with NPV of $350,000 at the 10% WACC. Project Y requires $5,000,000 and has an IRR of 16% with NPV of $620,000 at the same WACC. The CFO argues Project X is superior due to its higher IRR. Evaluate this reasoning.', '["The CFO is correct because IRR is the preferred metric for comparing projects of any size", "The CFO is correct because higher IRR indicates greater value per dollar invested", "The CFO is incorrect — for mutually exclusive projects, NPV is the correct criterion, and Project Y''s $620,000 NPV creates more shareholder wealth", "Neither project should be accepted because conflicting signals indicate estimation error"]'::jsonb, 2, 'When IRR and NPV conflict for mutually exclusive projects due to scale differences, NPV is the correct decision criterion because it directly measures the dollar increase in shareholder wealth. Under ASC 820-10 fair value principles, value creation depends on absolute dollar returns. Project Y adds $620,000 versus $350,000. Choice B is incorrect because maximizing total shareholder wealth requires selecting the highest NPV, not the highest percentage return.', 'hard', 4),

-- Q19: medium / L3 — Asset tangibility and capital structure differences
(4, 'Capital Structure and Valuation', 'Ironbridge Steel has $200,000,000 in tangible fixed assets and maintains 55% debt. Nimbus Software has $5,000,000 in tangible assets with mostly intangible value and maintains 15% debt. Analyze the primary reason for the leverage difference.', '["Ironbridge''s tangible assets provide superior collateral, reducing lender risk and enabling higher leverage, while Nimbus''s intangible-heavy asset base limits borrowing capacity", "Nimbus avoids debt because software firms have higher tax rates, eliminating the interest tax shield", "Ironbridge uses more debt because the steel industry has a lower cost of equity", "Nimbus maintains low debt because its higher profit margins eliminate the need for external financing"]'::jsonb, 0, 'Under the trade-off theory and ASC 360-10 (long-lived tangible assets), tangible collateral reduces expected financial distress costs by providing recoverable value to lenders in default. Ironbridge''s heavy fixed assets support higher leverage. Nimbus''s primarily intangible value evaporates in distress, increasing lender risk. Choice D is incorrect because profit margins affect cash flow, not the collateral-based reason lenders restrict intangible-heavy firms'' borrowing.', 'medium', 3),

-- Q20: medium / L3 — Free cash flow hypothesis and agency costs
(4, 'Capital Structure and Valuation', 'Langford Energy generates $25,000,000 in annual free cash flow but has no positive-NPV projects. The CEO proposes retaining the cash. A large institutional shareholder argues the firm should issue debt and pay a special dividend. Analyze the shareholder''s reasoning under the free cash flow hypothesis.', '["The shareholder is wrong because retaining cash maximizes financial flexibility for future investments", "The shareholder is correct because debt and dividends reduce excess cash that management might waste, aligning manager and shareholder interests", "The shareholder is wrong because issuing debt increases financial risk with no offsetting benefit", "The shareholder is correct because dividends always increase stock price under M-M theory"]'::jsonb, 1, 'Under Jensen''s free cash flow hypothesis (1986) and consistent with ASC 505 equity guidance, excess cash flow with no positive-NPV uses creates agency risk — managers may invest in empire-building or value-destroying projects. Debt obligations and dividend payouts discipline management by reducing discretionary cash. Choice A is incorrect because it overlooks that financial flexibility without investment discipline can lead to value destruction through poor capital allocation.', 'medium', 3),

-- Q21: medium / L2 — Return on invested capital calculation
(4, 'Capital Structure and Valuation', 'Hawkstone Holdings reports NOPAT of $1,500,000. Total debt is $5,000,000, total equity is $10,000,000, and cash is $2,500,000. Calculate Hawkstone''s return on invested capital.', '["10.0%", "15.0%", "12.0%", "30.0%"]'::jsonb, 2, 'Return on invested capital equals NOPAT divided by invested capital (debt + equity − cash). For Hawkstone: $1,500,000 ÷ ($5,000,000 + $10,000,000 − $2,500,000) = $1,500,000 ÷ $12,500,000 = 12.0%. Subtracting cash yields capital actually deployed in operations. Under valuation principles consistent with ASC 820, ROIC measures operating return on productive capital. Choice A (10.0%) is incorrect because it includes cash in invested capital, understating the return on deployed resources.', 'medium', 2),

-- Q22: hard / L4 — Weighted marginal cost of capital break point
(4, 'Capital Structure and Valuation', 'Riverdale Industries has a target structure of 40% debt and 60% equity. Retained earnings for the year are $3,600,000 at a cost of 13%. Issuing new common stock costs 15% due to flotation costs. The after-tax cost of debt is 5%. Evaluate the total level of new capital at which the weighted marginal cost of capital first increases.', '["$3,600,000, equal to the retained earnings amount", "$9,000,000, computed by dividing retained earnings by the debt weight", "$5,400,000, computed by multiplying retained earnings by the equity weight", "$6,000,000, computed by dividing retained earnings by the equity weight of 60%"]'::jsonb, 3, 'Under marginal cost of capital theory consistent with ASC 470 and ASC 505 capital structure guidance, the break point equals retained earnings divided by the equity weight: $3,600,000 ÷ 0.60 = $6,000,000. Below this threshold, equity is funded from cheaper retained earnings (13%); above it, costlier new equity (15%) raises WACC from 9.8% to 11.0%. Choice A is incorrect because it uses the raw retained earnings figure without dividing by the equity proportion, understating the break point.', 'hard', 4),

-- Q23: hard / L3 — Depreciation method effect on tax shields and leverage
(4, 'Capital Structure and Valuation', 'Ashdale Manufacturing considers two depreciation scenarios for a $5,000,000 asset at a 25% tax rate. Under MACRS, the first-year depreciation rate is 20%, producing a $250,000 tax shield. Under straight-line over 10 years, the first-year shield is $125,000. Analyze how the depreciation method affects borrowing capacity.', '["Accelerated depreciation front-loads tax shields, increasing their present value and supporting higher leverage through greater early cash flow", "Straight-line is preferred because equal annual tax shields simplify debt service planning", "The depreciation method has no effect on capital structure because depreciation and interest shields are independent", "Accelerated depreciation reduces borrowing capacity because lower reported income increases perceived lender risk"]'::jsonb, 0, 'Under ASC 740 (Income Taxes) and IRC Section 168 (MACRS), accelerated depreciation generates larger tax deductions in early years, increasing the present value of total tax shields versus straight-line. Higher early-year cash flows improve debt service coverage, effectively increasing borrowing capacity. Choice D is incorrect because lenders evaluating debt capacity focus on cash flow coverage, not accounting income — and accelerated depreciation increases cash flow despite lowering reported earnings.', 'hard', 3),

-- Q24: easy / L1 — Debt overhang problem definition
(4, 'Capital Structure and Valuation', 'What is the debt overhang problem in capital structure theory?', '["The tendency of profitable firms to use too little debt relative to their optimal structure", "A situation where a highly leveraged firm passes on positive-NPV projects because the value would primarily benefit existing creditors rather than shareholders", "The risk that short-term debt must be refinanced at higher interest rates", "The difference between a firm''s target and actual debt-to-equity ratios"]'::jsonb, 1, 'Under ASC 470-10 debt guidance, debt overhang (Myers, 1977) occurs when a firm has so much existing debt that any new value created by investment flows largely to creditors, not shareholders. Shareholders rationally reject positive-NPV projects because the upside accrues to bondholders, leading to underinvestment. Choice C is incorrect because it describes refinancing risk, which is distinct from the investment distortion caused by excessive outstanding debt.', 'easy', 1),

-- Q25: easy / L2 — P/E ratio valuation
(4, 'Capital Structure and Valuation', 'Ridgefield Consulting has earnings per share of $4.50. Comparable firms trade at an average price-to-earnings ratio of 18x. Using the P/E multiple approach, determine Ridgefield''s estimated share price.', '["$72.00", "$22.50", "$81.00", "$90.00"]'::jsonb, 2, 'Under the market approach consistent with ASC 820-10-35, share price = EPS × P/E multiple = $4.50 × 18 = $81.00. The comparable company P/E method assumes similar growth and risk profiles among peer firms. Choice B ($22.50) is incorrect because it adds the P/E ratio to EPS rather than multiplying, confusing the additive and multiplicative relationships between earnings and the valuation multiple.', 'easy', 2),

-- Q26: medium / L2 — NOPAT calculation
(4, 'Capital Structure and Valuation', 'Westfield Corp. reports operating income of $6,000,000 for the year ended December 31, 2025. The effective corporate tax rate is 25%. Calculate Westfield''s net operating profit after tax.', '["$6,000,000", "$7,500,000", "$1,500,000", "$4,500,000"]'::jsonb, 3, 'Net operating profit after tax equals EBIT × (1 − tax rate) = $6,000,000 × 0.75 = $4,500,000. Under valuation principles consistent with ASC 740, NOPAT isolates after-tax operating performance independent of capital structure decisions. Choice A ($6,000,000) is incorrect because it represents the pre-tax operating income, failing to account for the tax obligation and overstating the cash profit available to all capital providers.', 'medium', 2),

-- Q27: easy / L1 — M-M Proposition II without taxes
(4, 'Capital Structure and Valuation', 'Under Modigliani-Miller Proposition II without taxes, what happens to the cost of equity as leverage increases?', '["The cost of equity increases linearly with the debt-to-equity ratio, compensating shareholders for added financial risk", "The cost of equity remains constant regardless of the capital structure", "The cost of equity decreases because debt is cheaper and lowers the overall cost", "The cost of equity first decreases then increases in a U-shaped pattern"]'::jsonb, 0, 'Under ASC 820 valuation principles, Modigliani-Miller Proposition II (1958) without taxes states that ke = k0 + (k0 − kd) × (D/E), where the cost of equity rises linearly with leverage. This increase exactly offsets the benefit of cheaper debt, keeping WACC constant per Proposition I. Choice B is incorrect because it describes firm value constancy (Proposition I), not cost of equity behavior (Proposition II), which explicitly rises with leverage.', 'easy', 1),

-- Q28: easy / L2 — Debt-to-total-capital ratio
(4, 'Capital Structure and Valuation', 'Pennfield Enterprises has total debt of $8,000,000 and total equity of $12,000,000. Calculate Pennfield''s debt-to-total-capital ratio.', '["66.7%", "40.0%", "60.0%", "150.0%"]'::jsonb, 1, 'The debt-to-total-capital ratio equals debt ÷ (debt + equity) = $8,000,000 ÷ $20,000,000 = 40.0%. This ratio measures the proportion of total capital provided by debt. Under capital structure analysis consistent with ASC 470, it is distinct from the debt-to-equity ratio. Choice A (66.7%) is incorrect because it computes debt-to-equity ($8M ÷ $12M), which measures leverage relative to equity alone rather than total capital.', 'easy', 2),

-- Q29: hard / L4 — Evaluate competing capital structure theories
(4, 'Capital Structure and Valuation', 'Carrington Energy, a regulated utility with stable annual cash flows of $50,000,000 and tangible assets of $400,000,000, maintains 55% debt. Zenith Software, a high-growth tech firm with volatile earnings and primarily intangible assets, operates at 10% debt. Evaluate which theory best explains this cross-industry leverage difference.', '["The pecking order theory, because both firms exhaust internal funds before seeking external financing", "The M-M irrelevance proposition, because the leverage difference is random and unrelated to firm characteristics", "The signaling theory, because Carrington uses high debt to signal confidence while Zenith avoids it", "The static trade-off theory, because Carrington''s stable cash flows and tangible assets support higher debt with lower distress costs, while Zenith''s volatility and intangibles increase distress costs"]'::jsonb, 3, 'Under the static trade-off theory consistent with ASC 470 and ASC 820 principles, firms balance tax benefits of debt against expected financial distress costs. Carrington''s predictable cash flows and tangible collateral reduce distress probability, making higher leverage optimal. Zenith''s volatile earnings and intangibles raise expected distress costs. Choice A is incorrect because the pecking order predicts financing hierarchy but does not explain why different industries maintain systematically different target leverage ratios.', 'hard', 4),

-- Q30: easy / L2 — Retention ratio calculation
(4, 'Capital Structure and Valuation', 'Ashgrove Partners reports earnings per share of $5.00 and pays an annual dividend of $1.50 per share. Determine the retention ratio and the earnings per share reinvested in the business.', '["30% retention ratio; $1.50 reinvested per share", "77% retention ratio; $3.85 reinvested per share", "70% retention ratio; $3.50 reinvested per share", "100% retention ratio; $5.00 reinvested per share"]'::jsonb, 2, 'Under ASC 505 equity principles, the retention ratio equals (EPS − dividends per share) ÷ EPS = ($5.00 − $1.50) ÷ $5.00 = 70%, meaning $3.50 per share is reinvested. The retention ratio is the complement of the payout ratio (30%), and retained earnings fund internal growth. Choice A is incorrect because it reports the 30% payout ratio as the retention ratio, confusing the portion distributed with the portion retained.', 'easy', 2)
;

COMMIT;
